-- Executable fixtures against the additive migration, never customer data.
create function public.monitor_assert(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'ASSERT: %',message;end if;end$$;
create function public.monitor_payload(email boolean default true) returns jsonb language sql as $$select jsonb_build_object('wallet','0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','coverage','aave','threshold_raw','1200000000000000000','recovery_raw','1300000000000000000','enabled',true,'email_opt_in',email)$$;
create function public.monitor_evidence(c jsonb,condition text,health text default '1100000000000000000') returns jsonb language sql as $$select c||jsonb_build_object('result',jsonb_build_object('condition',condition,'coverage','aave','health_raw',health,'block_number','30000000','block_hash','0x'||repeat('a',64),'block_timestamp',floor(extract(epoch from now()))))$$;
set role service_role;
select public.rivexis_defi_monitor_job('heartbeat','{"evaluation_enabled":true,"email_enabled":true}');
select public.rivexis_defi_monitor_manage('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','save',public.monitor_payload());
select public.rivexis_defi_monitor_manage('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','save',public.monitor_payload(false)||'{"enabled":false}');
do $$declare c jsonb;d jsonb;n integer;begin
 c:=public.rivexis_defi_monitor_job('claim');
 perform public.monitor_assert(c->>'owner_id'='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','due owner claimed');
 perform public.monitor_assert(public.rivexis_defi_monitor_job('claim')='null'::jsonb,'overlapping cron cannot claim lease');
 perform public.rivexis_defi_monitor_job('complete',public.monitor_evidence(c,'BREACH'));
 perform public.monitor_assert((public.rivexis_defi_monitor_job('complete',public.monitor_evidence(c,'BREACH'))->>'committed')::boolean=false,'duplicate job cannot commit twice');
 select count(*) into n from public.rivexis_defi_monitor_events;perform public.monitor_assert(n=1,'single durable breach');
 perform public.rivexis_defi_monitor_manage('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','save',public.monitor_payload());
 perform public.monitor_assert((select version=1 and condition='BREACH' from public.rivexis_defi_monitor_rules where owner_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'identical save is idempotent');
 d:=public.rivexis_defi_monitor_job('claim_delivery');
 perform public.monitor_assert(d->>'recipient'='first@example.invalid','recipient comes only from verified auth identity');
 perform public.rivexis_defi_monitor_job('mark_delivery',d||'{"state":"ACCEPTED","message_id":"test-receipt"}');
 perform public.monitor_assert((select state='ACCEPTED' from public.rivexis_defi_monitor_events where id=(d->>'id')::uuid),'acceptance is not delivery');
 perform public.rivexis_defi_monitor_job('receipt',d||'{"state":"DELIVERED","message_id":"wrong"}');
 perform public.monitor_assert((select state='ACCEPTED' from public.rivexis_defi_monitor_events where id=(d->>'id')::uuid),'unmatched receipt ignored');
 perform public.rivexis_defi_monitor_job('receipt',d||'{"state":"DELIVERED","message_id":"test-receipt"}');
 perform public.monitor_assert((select state='DELIVERED' from public.rivexis_defi_monitor_events where id=(d->>'id')::uuid),'matched delivery receipt');
 update public.rivexis_defi_monitor_rules set next_evaluation_at=now()-interval '1 second' where id=(c->>'id')::uuid;
 c:=public.rivexis_defi_monitor_job('claim');perform public.rivexis_defi_monitor_job('unavailable',c);
 perform public.monitor_assert((select condition='BREACH' and last_status='UNAVAILABLE' and next_evaluation_at>now() from public.rivexis_defi_monitor_rules where id=(c->>'id')::uuid),'outage never means recovery and has backoff');
 update public.rivexis_defi_monitor_rules set next_evaluation_at=now()-interval '1 second' where id=(c->>'id')::uuid;
 c:=public.rivexis_defi_monitor_job('claim');perform public.rivexis_defi_monitor_job('complete',public.monitor_evidence(c,'CLEAR','1400000000000000000'));
 select count(*) into n from public.rivexis_defi_monitor_events where kind='RECOVERY';perform public.monitor_assert(n=1,'one recovery per episode');
 d:=public.rivexis_defi_monitor_job('claim_delivery');
 update public.rivexis_defi_monitor_events set delivery_started_at=now()-interval '3 minutes' where id=(d->>'id')::uuid;
 perform public.rivexis_defi_monitor_job('claim_delivery');
 perform public.monitor_assert((select state='UNKNOWN' from public.rivexis_defi_monitor_events where id=(d->>'id')::uuid),'crashed send is held unknown, never requeued');
 update public.rivexis_defi_monitor_rules set next_evaluation_at=now()-interval '1 second' where id=(c->>'id')::uuid;
 c:=public.rivexis_defi_monitor_job('claim');
 perform public.rivexis_defi_monitor_manage('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','save',public.monitor_payload()||'{"email_opt_in":false}');
 perform public.monitor_assert((public.rivexis_defi_monitor_job('complete',public.monitor_evidence(c,'BREACH'))->>'committed')::boolean=false,'changed consent fences old lease');
 c:=public.rivexis_defi_monitor_job('claim');perform public.rivexis_defi_monitor_job('complete',public.monitor_evidence(c,'BREACH'));
 select count(*) into n from public.rivexis_defi_monitor_events;perform public.monitor_assert(n=2,'opt out creates no new email event');
 update public.rivexis_defi_monitor_rules set next_evaluation_at=now()-interval '1 second' where id=(c->>'id')::uuid;
 c:=public.rivexis_defi_monitor_job('claim');perform public.rivexis_defi_monitor_job('reorg',c);
 perform public.monitor_assert((select last_status='INVALIDATED' and condition='UNKNOWN' and last_success_at is null from public.rivexis_defi_monitor_rules where id=(c->>'id')::uuid),'reorg invalidates success evidence');
end$$;
reset role;
set role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',false);
select public.monitor_assert((select count(*)=1 from public.rivexis_defi_monitor_rules),'RLS hides other owner rules');
select public.monitor_assert((select count(*)=2 from public.rivexis_defi_monitor_events),'owner sees own events');
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',false);
select public.monitor_assert((select count(*)=0 from public.rivexis_defi_monitor_events),'cross-owner events denied');
do $$begin
 begin perform public.rivexis_defi_monitor_manage('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','read');raise exception 'client executed service RPC';exception when insufficient_privilege then null;end;
 begin update public.rivexis_defi_monitor_rules set owner_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';raise exception 'client wrote protected rules';exception when insufficient_privilege then null;end;
 begin insert into public.rivexis_defi_monitor_events(rule_id,owner_id,episode,kind,rule_version,block_number,block_hash) values(gen_random_uuid(),gen_random_uuid(),1,'BREACH',1,'1','fake');raise exception 'client forged event';exception when insufficient_privilege then null;end;
 begin perform lease_token from public.rivexis_defi_monitor_rules;raise exception 'client read worker lease';exception when insufficient_privilege then null;end;
 begin perform delivery_token from public.rivexis_defi_monitor_events;raise exception 'client read delivery lease';exception when insufficient_privilege then null;end;
end$$;
reset role;
set role anon;
do $$begin begin perform * from public.rivexis_defi_monitor_rules;raise exception 'guest read rules';exception when insufficient_privilege then null;end;end$$;
reset role;
select public.monitor_assert((select count(*)=3 from pg_tables where schemaname='public' and tablename like 'rivexis_defi_monitor_%' and rowsecurity),'RLS on all new tables');
select public.monitor_assert(not has_function_privilege('authenticated','public.rivexis_defi_monitor_job(text,jsonb)','execute'),'job never client callable');
select 'Monitoring storage fixtures passed' as result;
